"""Parser checks only; runtime mutation evidence is generated by the CI job."""
import unittest

from mechanism_negative_control import DIAGNOSTICS, validate
from habitat_negative_control import EXPECTED_BATCHES


def rejected_log():
    lines = [f"Running test batch '{batch}:1' ({count} tests)" for batch, count in EXPECTED_BATCHES.items()]
    for name, reasons in DIAGNOSTICS.items():
        lines.append(f"[minecraft/LogTestReporter]: {name} failed! {reasons[0]}")
    lines.extend([f"{sum(EXPECTED_BATCHES.values())} GAME TESTS COMPLETE", f"{len(DIAGNOSTICS)} required tests failed"])
    lines.extend(f"[minecraft/GameTestServer]:    - {name}" for name in DIAGNOSTICS)
    return "\n".join(lines + ["BUILD FAILED"])


class MechanismNegativeControlTests(unittest.TestCase):
    def test_accepts_complete_exact_behavior_failures(self):
        self.assertEqual(validate(rejected_log(), 1)["completed"], 91)

    def test_rejects_timeout_instead_of_behavior_failure(self):
        log = rejected_log().replace(next(iter(DIAGNOSTICS.values()))[0], "Didn't succeed within 600 ticks")
        with self.assertRaises(AssertionError):
            validate(log, 1)

    def test_rejects_missing_expected_case_and_success_exit(self):
        for log, code in ((rejected_log().replace("iron bars are not solid squeeze walls", "unexpected fixture error"), 1),
                          (rejected_log(), 0), ("BUILD FAILED", 1)):
            with self.subTest(code=code), self.assertRaises(AssertionError):
                validate(log, code)
